/* bmsInab.selectAbnormalCorrList : 반입이상정정 리스트 조회 */
SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT , SUM(AA.SIMPLE_CNT) OVER() AS TOTAL_SIMPLE_CNT , SUM(AA.GENERAL_CNT) OVER() AS TOTAL_GENERAL_CNT FROM ( SELECT A.SIMPLE_CNT , A.GENERAL_CNT , A.FILE_SHARE , A.LAST_POD_STATUS , A.CHANGE_CLASS , A.ABN_CHANGE_NO , A.SEQ_NO , A.CARGO_REFERENCE_NO , A.CARGO_REFERENCE_NO_DISP , A.HSN , A.BL_NO , A.PKG_TYPE , A.EX_CT , A.EX_WT , A.CT , A.WT , A.ACCIDENT_CLASS , A.ACCIDENT_CT , A.ACCIDENT_WT , A.REJECT_REASON , A.REGISTER_USER_ID , A.REGISTER_USER_NAME , A.REGISTER_DATE_TIME , A.UPDATE_USER_ID , A.UPDATE_USER_NAME , A.UPDATE_DATE_TIME , A.CUSTOMS_REPORT_NO , A.MRN , A.MSN , A.MBL_NO , A.LAST_POD_DATE , A.LAST_POD_RAQ_DATE , A.VESSEL_FLIGHT , A.VOYAGE , A.AR_DATE , A.AR_TIME , A.CHANGE_DATE , A.CHANGE_COUNT , A.CHANGE_REASON , A.OD_JOB_NO FROM ( SELECT IIF(IP.CD_TYPE = 'Y', 1, 0) AS SIMPLE_CNT , IIF(IP.CD_TYPE = 'N', 1, 0) AS GENERAL_CNT , CASE WHEN (SELECT TOP 1 REFERENCE_NO_ID FROM TB_COM_FILE_SHARE WHERE FUNC_JOB_NO = IP.OD_JOB_NO) IS NULL THEN 'N' ELSE 'Y' END AS FILE_SHARE
, (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'STATUS_ORDER_CARGO' AND CODE = A.LAST_POD_STATUS) AS LAST_POD_STATUS , CASE WHEN CB.CHANGE_CLASS = '01' THEN '01.추가' WHEN CB.CHANGE_CLASS = '02' THEN '02.삭제' WHEN CB.CHANGE_CLASS = '03' THEN '03.변경' END AS CHANGE_CLASS
, A.LAST_POD_STATUS , CB.CHANGE_CLASS
, CB.ABN_CHANGE_NO , CB.SEQ_NO , CB.CARGO_REFERENCE_NO , CASE WHEN LEN(CB.CARGO_REFERENCE_NO) > 15 THEN ( SUBSTRING(CB.CARGO_REFERENCE_NO, 1, 11) + '-' + SUBSTRING(CB.CARGO_REFERENCE_NO, 12, 4) + '-' + SUBSTRING(CB.CARGO_REFERENCE_NO, 16, 4) ) ELSE SUBSTRING(CB.CARGO_REFERENCE_NO, 1, 11) + '-' + SUBSTRING(CB.CARGO_REFERENCE_NO, 12, 4) END AS CARGO_REFERENCE_NO_DISP , CB.HSN , CB.BL_NO , CB.PKG_TYPE , CB.EX_CT , CB.EX_WT , CB.CT , CB.WT , CB.ACCIDENT_CLASS , CB.ACCIDENT_CT , CB.ACCIDENT_WT , CB.REJECT_REASON , CB.REGISTER_USER_ID , (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = CB.REGISTER_USER_ID) AS REGISTER_USER_NAME , CB.REGISTER_DATE_TIME , CB.UPDATE_USER_ID , (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = CB.UPDATE_USER_ID) AS UPDATE_USER_NAME , CB.UPDATE_DATE_TIME , A.CUSTOMS_REPORT_NO , A.MRN , A.MSN , A.MBL_NO , A.LAST_POD_DATE , A.LAST_POD_RAQ_DATE , A.VESSEL_FLIGHT , A.VOYAGE , A.AR_DATE , A.AR_TIME , A.CHANGE_DATE , A.CHANGE_COUNT , A.CHANGE_REASON , IP.OD_JOB_NO , ROW_NUMBER() OVER (PARTITION BY A.ABN_CHANGE_NO, A.CHANGE_COUNT ORDER BY A.ABN_CHANGE_NO DESC) AS RN FROM TB_BMS_ABNORMAL_CHANGE_BL CB LEFT JOIN TB_BMS_ABNORMAL_CHANGE A ON A.ABN_CHANGE_NO = CB.ABN_CHANGE_NO LEFT JOIN TB_BMS_IN_PLAN IP WITH (NOLOCK) ON IP.CARGO_REFERENCE_NO = CB.CARGO_REFERENCE_NO
) A WHERE A.RN = 1 ) AA

SELECT
    COUNT(*)
FROM TB_BMS_ABNORMAL_CHANGE
WHERE 1 = 1

    AND ABN_CHANGE_NO = #{abnChangeNo}


    AND CUSTOMS_REPORT_NO = #{customsReportNo}

mapper.insert:
INSERT INTO TB_BMS_ABNORMAL_CHANGE (
      CUSTOMS_REPORT_NO
    , MRN
    , MSN
    , MBL_NO
    , LAST_POD_DATE
    , LAST_POD_STATUS
    , LAST_POD_RAQ_DATE
    , VESSEL_FLIGHT
    , VOYAGE
    , AR_DATE
    , AR_TIME
    , CHANGE_DATE
    , CHANGE_COUNT
    , CHANGE_REASON
    , REGISTER_USER_ID
    , REGISTER_DATE_TIME
    , UPDATE_USER_ID
    , UPDATE_DATE_TIME )
VALUES (
      #{customsReportNo}
    , #{mrn}
    , #{msn}
    , #{mblNo}
    , ''
    , 'BMS01'
    , ''
    , #{vesselFlight}
    , #{voyage}
    , #{arDate}
    , #{arTime}
    , #{changeDate}
    , #{changeCount}
    , #{changeReason}
    , #{registerUserId}
    , GETDATE()
    , #{updateUserId}
    , GETDATE()
    )

INSERT INTO TB_BMS_ABNORMAL_CHANGE_BL (
      ABN_CHANGE_NO
    , SEQ_NO
    , CARGO_REFERENCE_NO
    , HSN
    , BL_NO
    , CHANGE_CLASS
    , PKG_TYPE
    , EX_CT
    , EX_WT
    , CT
    , WT
    , ACCIDENT_CLASS
    , ACCIDENT_CT
    , ACCIDENT_WT
    , REJECT_REASON
    , REGISTER_USER_ID
    , REGISTER_DATE_TIME
    , UPDATE_USER_ID
    , UPDATE_DATE_TIME )
VALUES (
      #{abnChangeNo}
    , (SELECT ISNULL(MAX(SEQ_NO),0) + 1 FROM TB_BMS_ABNORMAL_CHANGE_BL WHERE ABN_CHANGE_NO = #{abnChangeNo})
    , #{cargoReferenceNo}
    , #{hsn}
    , #{blNo}
    , #{changeClass}
    , #{pkgType}
    , #{exCt}
    , #{exWt}
    , #{ct}
    , #{wt}
    , #{accidentClass}
    , #{accidentCt}
    , #{accidentWt}
    , #{rejectReason}
    , #{registerUserId}
    , GETDATE()
    , #{updateUserId}
    , GETDATE()
        )

mapper.select:
SELECT A.ABN_CHANGE_NO , A.CUSTOMS_REPORT_NO , A.MRN , A.MSN , A.MBL_NO , A.LAST_POD_DATE , A.LAST_POD_STATUS , A.LAST_POD_RAQ_DATE , A.VESSEL_FLIGHT , A.VOYAGE , A.AR_DATE , A.AR_TIME , A.CHANGE_DATE , A.CHANGE_COUNT , A.CHANGE_CLASS , A.CHANGE_REASON , A.REGISTER_USER_ID , (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = A.REGISTER_USER_ID) AS REGISTER_USER_NAME , A.REGISTER_DATE_TIME , A.UPDATE_USER_ID , (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = A.UPDATE_USER_ID) AS UPDATE_USER_NAME , A.UPDATE_DATE_TIME , (SELECT BMS_CUSTOMS_CODE FROM TB_SMS_ENT_BUSINESS WHERE ENT_CODE =#{entCode} AND ENT_BUSINESS_CODE = #{entBusinessCode}) AS CUSTOMS_CODE , (SELECT BMS_CUSTOMS_DPT_CODE FROM TB_SMS_ENT_BUSINESS WHERE ENT_CODE =#{entCode} AND ENT_BUSINESS_CODE = #{entBusinessCode}) AS CUSTOMS_DPT_CODE FROM TB_BMS_ABNORMAL_CHANGE A WHERE 1 = 1
AND A.ABN_CHANGE_NO = #{abnChangeNo}
AND ABN_CHANGE_NO = (SELECT MAX(ABN_CHANGE_NO) FROM TB_BMS_ABNORMAL_CHANGE WHERE CUSTOMS_REPORT_NO = #{customsReportNo})

mapper.update:
UPDATE TB_BMS_ABNORMAL_CHANGE
SET
    CHANGE_DATE = #{changeDate}
  , CHANGE_REASON = #{changeReason}
  , UPDATE_USER_ID = #{updateUserId}
  , UPDATE_DATE_TIME = GETDATE()

  , LAST_POD_STATUS = 'BMS01'
  , LAST_POD_DATE = ''
  , LAST_POD_RAQ_DATE = ''

WHERE 1 = 1
  AND ABN_CHANGE_NO = #{abnChangeNo}
